// fixtureDir is the raw-evidence directory of oracle-engine fixtures
// (test/parity/probes/0011-collab-crdt, generated by pycrdt 0.14.10).
func fixtureDir(t *testing.T) string {
	t.Helper()
	dir := os.Getenv("CRDT_FIXTURE_DIR")
	if dir == "" {
		dir = filepath.Join("..", "..", "test", "parity", "probes", "0011-collab-crdt")
	}
	if _, err := os.Stat(filepath.Join(dir, "meta.json")); err != nil {
		t.Fatalf("fixture dir missing (run generate.py): %v", err)
	}
	return dir
}

func readBin(t *testing.T, dir, rel string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, rel))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func readJSON(t *testing.T, dir, rel string, into any) {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, rel))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, into); err != nil {
		t.Fatalf("%s: %v", rel, err)
	}
}

// assertDocEq compares the Go document view with the oracle's
// ydoc_to_document output as JSON values (1 == 1.0, bool is not 1 - the
// same equality apps/collab/schema.json_equal defines).
func assertDocEq(t *testing.T, got map[string]any, fixture, rel string) {
	t.Helper()
	var want any
	readJSON(t, fixtureDir(t), rel, &want)
	gotJSON, err := json.Marshal(got)
	if err != nil {
		t.Fatal(err)
	}
	var gotAny any
	if err := json.Unmarshal(gotJSON, &gotAny); err != nil {
		t.Fatal(err)
	}
	if !jsonEqual(gotAny, want) {
		gb, _ := json.MarshalIndent(gotAny, "", " ")
		wb, _ := json.MarshalIndent(want, "", " ")
		t.Fatalf("%s: document view differs from oracle\n got: %s\nwant: %s", rel, gb, wb)
	}
}

func jsonEqual(a, b any) bool {
	if av, aok := a.(float64); aok {
		bv, bok := b.(float64)
		return aok && bok && av == bv
	}
	return reflect.DeepEqual(a, b)
}

// TestSnapshotsRoundTrip: oracle snapshot -> Go document view equals the
// oracle's own ydoc_to_document output, and the state vectors byte-match.
func TestSnapshotsRoundTrip(t *testing.T) {
	dir := fixtureDir(t)
	for _, name := range []string{"basic", "unicode", "numbers", "empty"} {
		t.Run(name, func(t *testing.T) {
			d := NewDoc()
			if err := ApplyUpdate(d, readBin(t, dir, name+".snapshot.bin")); err != nil {
				t.Fatalf("apply: %v", err)
			}
			doc, err := ToDocument(d)
			if err != nil {
				t.Fatalf("to document: %v", err)
			}
			assertDocEq(t, doc, dir, name+".roundtrip.json")
			sv, err := StateVector(d)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(sv, readBin(t, dir, name+".sv.bin")) {
				t.Fatalf("state vector mismatch:\n got %x\nwant %x", sv, readBin(t, dir, name+".sv.bin"))
			}
		})
	}
}

// TestEditStream replays the oracle's incremental transaction updates and
// must land on both the oracle's final document and state vector.
func TestEditStream(t *testing.T) {
	dir := fixtureDir(t)
	d := NewDoc()
	if err := ApplyUpdate(d, readBin(t, dir, "edits/base.snapshot.bin")); err != nil {
		t.Fatalf("base: %v", err)
	}
	entries, err := os.ReadDir(filepath.Join(dir, "edits"))
	if err != nil {
		t.Fatal(err)
	}
	applied := 0
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) != ".update" {
			continue
		}
		if err := ApplyUpdate(d, readBin(t, dir, "edits/"+e.Name())); err != nil {
			t.Fatalf("%s: %v", e.Name(), err)
		}
		applied++
	}
	if applied != 12 {
		t.Fatalf("expected 12 edit updates, found %d", applied)
	}
	doc, err := ToDocument(d)
	if err != nil {
		t.Fatal(err)
	}
	assertDocEq(t, doc, dir, "edits/final.json")
	sv, err := StateVector(d)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(sv, readBin(t, dir, "edits/final.sv.bin")) {
		t.Fatalf("state vector mismatch after replay:\n got %x\nwant %x", sv, readBin(t, dir, "edits/final.sv.bin"))
	}

	// merge_updates(*edits) (the compaction path) applied WITHOUT the base
	// patch must land on the same document.
	m := NewDoc()
	if err := ApplyUpdate(m, readBin(t, dir, "edits/base.snapshot.bin")); err != nil {
		t.Fatal(err)
	}
	if err := ApplyUpdate(m, readBin(t, dir, "edits/merge_updates.bin")); err != nil {
		t.Fatalf("merge_updates fixture: %v", err)
	}
	mdoc, err := ToDocument(m)
	if err != nil {
		t.Fatal(err)
	}
	assertDocEq(t, mdoc, dir, "edits/final.json")

	// The oracle's own full-state compaction (merged_apply.bin) from empty.
	full := NewDoc()
	if err := ApplyUpdate(full, readBin(t, dir, "edits/merged_apply.bin")); err != nil {
		t.Fatal(err)
	}
	fdoc, err := ToDocument(full)
	if err != nil {
		t.Fatal(err)
	}
	assertDocEq(t, fdoc, dir, "edits/final.json")

	// Go's merge path (ApplyToFresh over the incremental batches) lands on
	// the same document and state vector.
	batches := [][]byte{readBin(t, dir, "edits/base.snapshot.bin")}
	for _, e := range entries {
		if !e.IsDir() && filepath.Ext(e.Name()) == ".update" {
			batches = append(batches, readBin(t, dir, "edits/"+e.Name()))
		}
	}
	merged, err := ApplyToFresh(batches[0], batches[1:]...)
	if err != nil {
		t.Fatal(err)
	}
	g := NewDoc()
	if err := ApplyUpdate(g, merged); err != nil {
		t.Fatal(err)
	}
	gdoc, err := ToDocument(g)
	if err != nil {
		t.Fatal(err)
	}
	assertDocEq(t, gdoc, dir, "edits/final.json")
}

// TestConcurrentConvergence: the oracle's concurrent left/right streams must
// converge in Go to the oracle's converged document (both orders).
func TestConcurrentConvergence(t *testing.T) {
	dir := fixtureDir(t)
	left := readBin(t, dir, "conc/left.update")
	right := readBin(t, dir, "conc/right.update")

	build := func(first, second []byte) map[string]any {
		d := NewDoc()
		if err := ApplyUpdate(d, first); err != nil {
			t.Fatalf("apply first: %v", err)
		}
		if err := ApplyUpdate(d, second); err != nil {
			t.Fatalf("apply second: %v", err)
		}
		doc, err := ToDocument(d)
		if err != nil {
			t.Fatal(err)
		}
		return doc
	}
	v1 := build(left, right)
	assertDocEq(t, v1, dir, "conc/merged.json")
	v2 := build(right, left)
	assertDocEq(t, v2, dir, "conc/merged.json")
	// The oracle's left doc applied right's stream: same converged state.
	l := NewDoc()
	if err := ApplyUpdate(l, left); err != nil {
		t.Fatal(err)
	}
	if err := ApplyUpdate(l, right); err != nil {
		t.Fatal(err)
	}
	ldoc, err := ToDocument(l)
	if err != nil {
		t.Fatal(err)
	}
	assertDocEq(t, ldoc, dir, "conc/merged_from_left.json")
	// Converged state vectors are order-independent and must match.
	sv1, _ := StateVector(buildDoc(t, left, right))
	sv2, _ := StateVector(buildDoc(t, right, left))
	if !bytes.Equal(sv1, sv2) {
		t.Fatalf("converged state vectors differ: %x vs %x", sv1, sv2)
	}
}

func buildDoc(t *testing.T, first, second []byte) *Doc {
	t.Helper()
	d := NewDoc()
	if err := ApplyUpdate(d, first); err != nil {
		t.Fatal(err)
	}
	if err := ApplyUpdate(d, second); err != nil {
		t.Fatal(err)
	}
	return d
}

// TestGoUpdatesForOracleWitness: with CRDT_WRITE_WITNESS set, write Go-side
// edits (as a client would) for verify.py to apply under the oracle engine —
// the reverse direction of the conformance proof.
func TestGoUpdatesForOracleWitness(t *testing.T) {
	out := os.Getenv("CRDT_WRITE_WITNESS")
	if out == "" {
		t.Skip("set CRDT_WRITE_WITNESS=<dir> to emit Go-generated updates for verify.py")
	}
	dir := fixtureDir(t)
	d := NewDoc()
	if err := ApplyUpdate(d, readBin(t, dir, "basic.snapshot.bin")); err != nil {
		t.Fatal(err)
	}
	m := d.GetMap("meta")
	order := d.GetArray("pageOrder")
	pages := d.GetMap("pages")

	d.Transact(func() {
	m.Set("title", "Go-edited title")
	m.Set("counter", float64(7))
	m.Set("nested", map[string]any{"deep": []any{float64(1), "two", true}})
	order.Push("88888888-8888-4888-8888-888888888888")
	// Nested Y types like document_to_ydoc builds them - and the builder
	// discipline: insert the node into its parent BEFORE populating it, so
	// children follow the type item in clock order.
	newPage := yjsgo.NewNestedMap(d)
	pages.Set("88888888-8888-4888-8888-888888888888", newPage)
	newPage.Set("id", "88888888-8888-4888-8888-888888888888")
	newPage.Set("name", "From Go \u2713 \U0001f3a8")
	newObjects := yjsgo.NewNestedMap(d)
	newOrder := yjsgo.NewNestedArray(d)
	newPage.Set("objects", newObjects)
	newPage.Set("objectOrder", newOrder)
	if p, ok := pages.Get("11111111-1111-4111-8111-111111111111"); ok {
		if pm, isMap := p.(*yjsgo.Map); isMap {
			if objs, ok := pm.Get("objects"); ok {
				if om, isM := objs.(*yjsgo.Map); isM {
					if o, ok := om.Get("aaaaaaa1-0000-4000-8000-000000000001"); ok {
						if omm, isOM := o.(*yjsgo.Map); isOM {
							omm.Set("text", "Edited by the Go engine \u00e9\u0301")
							omm.Set("x", float64(99.5))
						}
					}
					om.Delete("aaaaaaa1-0000-4000-8000-000000000002")
				}
			}
		}
	}
	m.Delete("background")
	}, nil)
	full, err := Snapshot(d)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(out, "go_full.update"), full, 0o644); err != nil {
		t.Fatal(err)
	}
	doc, err := ToDocument(d)
	if err != nil {
		t.Fatal(err)
	}
	jb, err := json.Marshal(doc)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(out, "go_final.json"), jb, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("witness written to %s", out)
}
